-- Stage 2 of 2: the clean, conformed rows the marts consume.

-- Source systems replay batches, so the same business key can
-- arrive more than once. Keep the most recently ingested version.
with deduplicated as (
    select
        *,
        row_number() over (partition by replenishment_id order by ingested_at desc nulls last) as _row_rank
    from {{ ref('cln_fact_replenishment_orders') }}
    where _dq_is_valid
)

select
    replenishment_id,
    raised_ts,
    date_key,
    site_id,
    terminal_id,
    product_id,
    requested_litres,
    trigger_type,
    days_of_cover_at_raise,
    promised_delivery_ts,
    fulfilled_flag,
    source_system_code,
    ingested_at,
    _cleansed_at
from deduplicated
where _row_rank = 1
